#nullable enable // autogenerated

using System;
using UnityEngine;

namespace MVZ2.Sprites
{
    [Serializable]
    public class GeneratedTexture2D
    {
        public GeneratedTexture2D(Texture2D texture)
        {
            this.name = texture.name;
            this.texture = texture;
        }
        public string name;
        public Texture2D texture;
    }
}
